test('all16 anchors by3 contexts by6 profiles preserve all288 original outcomes',async()=>{
  const f=validateRetained(await readFile(fixture))
  const anchors=['80','bf','c0af','c1bf','f5808080','c228','e228a1','e08080','eda080','f02880a1','f0808080','f4908080','c2','e0a0','f09080','f48fbf']
  const profiles=[[64,64,'utf8'],[64,64,'unicode'],['max',64,'utf8'],['max',64,'unicode'],['max','max','utf8'],['max','max','unicode']]
  const expected=anchors.flatMap((anchor,i)=>['prefix','suffix','sandwich'].flatMap(context=>profiles.map(([source,targetWidth,target])=>({
    name:`utf8-context-${i<5?'illegal-lead':i<12?'malformed':'truncated'}-${anchor}-${context}-source${source}-to-${target}${targetWidth}`,
    anchor,context,source,targetWidth,target,hex:(context==='suffix'?'':'41')+anchor+(context==='prefix'?'':'42')
  }))))
  assert.equal(cases.length,288);assert.equal(cases.reduce((n,c)=>n+rowsFor(c).length,0),576)
  assert.deepEqual(cases.map(c=>c.name),expected.map(c=>c.name));assert.deepEqual(observed.map(([name])=>name),expected.map(c=>c.name))
  for(const run of f.runs)for(const [i,o]of run.observations.entries()){
    const spec=expected[i],oracle=observed[i][1]
    assert.equal(o.case.sourceWidth,spec.source);assert.equal(o.case.wireWidth,spec.source);assert.equal(o.case.targetWidth,spec.targetWidth)
    assert.equal(o.case.anchorHex,spec.anchor);assert.equal(o.case.context,spec.context);assert.equal(o.case.target,spec.target)
    assert.deepEqual(o.input,[{id:1,valueHex:null},{id:2,valueHex:spec.hex}])
    assert.deepEqual(o.readback.result.sets[1].rows,oracle.rows,o.case.name)
    assert.deepEqual(o.execution.result.errors.map(e=>[e.number,e.state,e.class]),oracle.errors,o.case.name)
    assert.deepEqual(o.execution.result.info.map(e=>[e.number,e.state,e.class]),oracle.info,o.case.name)
    assert.deepEqual(o.readback.result.sets[0].rows,oracle.counters,o.case.name)
    assert.equal(o.readback.session,'original');assert.equal(o.recoveryReadback,undefined)
    assert.equal(o.execution.result.rowCount,oracle.errors.length?0:2)
    if(oracle.errors.length){assert.equal(o.execution.result.error.number,oracle.errors[0][0]);assert.deepEqual(oracle.rows,[])}
    else{assert.equal(o.execution.result.error,null);assert.deepEqual(oracle.rows[0],[1,null,null,null,null])}
  }
  const replay=spawnSync(process.execPath,['scripts/capture-bulk-character-utf8-context.mjs','--replay-fixture'],{cwd:new URL('../',import.meta.url),encoding:'utf8',env:{...process.env,PATH:''},timeout:15000})
  assert.equal(replay.status,0,replay.stderr)
})

test('uniform context/type/byte/unit/error/provenance corruption and omitted probes fail fixed pins',async()=>{
  const retained=await load()
  const changes=[
    ['utf8-context-malformed-c228-prefix-source64-to-utf864',o=>{o.execution.result.rowCount=99}],
    ['utf8-context-malformed-c228-prefix-source64-to-unicode64',o=>{o.case.sourceWidth='max'}],
    ['utf8-context-malformed-e08080-suffix-sourcemax-to-utf864',o=>{o.readback.result.sets[1].rows[1][4].value='fdfffdfffdff4200'}],
    ['utf8-context-malformed-eda080-suffix-sourcemax-to-utf864',o=>{o.readback.result.sets[1].rows[1][2].value='efbfbdefbfbdefbfbd42'}],
    ['utf8-context-truncated-c2-prefix-sourcemax-to-unicode64',o=>{o.execution.result.errors[0].number=4896}],
    ['utf8-context-malformed-c228-prefix-source64-to-unicode64',o=>{o.metadata.result.sets[0].columns[0].length=65535}],
    ['utf8-context-malformed-c228-prefix-source64-to-utf864',o=>{o.case.context='suffix'}]
  ]
  for(const [name,mutate]of changes){const f=structuredClone(retained);for(const run of f.runs)mutate(find(run,name));f.comparisons=f.runs.slice(1).map(r=>compare(r,f.runs[0]));assert.throws(()=>validate(f),/fixed/)}
  const omitted=structuredClone(retained);for(const run of omitted.runs)run.observations.pop();omitted.comparisons=omitted.runs.slice(1).map(r=>compare(r,omitted.runs[0]));assert.throws(()=>validate(omitted))
  for(const field of ['sourceSha','helperSha','nodeVersion']){const f=structuredClone(retained);f.provenance[field]='0'.repeat(64);assert.throws(()=>validate(f),/fixed/)}
  const f=structuredClone(retained);f.provenance.helpers['capture-bulk-character-utf8-bounded-target.mjs']='0'.repeat(64);assert.throws(()=>validate(f),/fixed/)
})

test('ASCII contexts change actual admission rather than inheriting isolated anchor classifications',async()=>{
  const f=await load(),bytes=await readCaptureFile(new URL('../reference/bulk-character-conversion.json',import.meta.url))
  assert.equal(createHash('sha256').update(bytes).digest('hex'),'f55527a2b0969d7104510d9b76a3303c82b28eac05d4ad11bc2acaf472caab27')
  const old=JSON.parse(bytes)
  for(const [ri,run]of f.runs.entries())for(const anchor of ['80','bf','c0af','c1bf','f5808080'])for(const target of ['utf8','unicode']){
    const previous=find(old.runs[ri],`utf8-${anchor}-${target}`)
    assert.deepEqual(previous.execution.result.errors.map(e=>[e.number,e.state,e.class]),[[9833,2,16]])
    assert.deepEqual(previous.readback.result.sets[1].rows,[])
    for(const context of ['prefix','suffix','sandwich']){
      const o=find(run,`utf8-context-illegal-lead-${anchor}-${context}-source64-to-${target}64`)
      if(context==='prefix'){
        assert.deepEqual(o.execution.result.errors.map(e=>[e.number,e.state,e.class]),anchor==='f5808080'?[[9833,2,16]]:[[7339,1,16]])
        assert.deepEqual(o.readback.result.sets[1].rows,[])
      }else{
        assert.deepEqual(o.execution.result.errors,[]);assert.equal(o.readback.result.sets[1].rows.length,2)
        const row=o.readback.result.sets[1].rows[1]
        assert.equal(row[2].value,target==='utf8'?o.input[1].valueHex:row[4].value)
        assert.deepEqual(o.readback.result.sets[0].rows,[[0,2,0,0]])
      }
    }
  }
})
